def transform(grid):
    h, w0 = len(grid), len(grid[0])
    # The framed panels occupy the left side; the first row gives the frame color and width.
    frame = grid[0][0]
    width = 0
    while width < w0 and grid[0][width] == frame:
        width += 1
    # Collect colored patterns from the right-hand side as normalized binary masks.
    patterns = {}
    for r in range(h):
        for c in range(width, w0):
            color = grid[r][c]
            if color:
                patterns.setdefault(color, set()).add((r, c))
    normalized = {}
    for color, cells in patterns.items():
        rmin = min(r for r, c in cells); rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells); cmax = max(c for r, c in cells)
        normalized[color] = {(r-rmin, c-cmin) for r,c in cells}
    out = [row[:width] for row in grid]
    # Panel boundaries are full-width rows of the frame color.
    borders = [r for r in range(h) if all(grid[r][c] == frame for c in range(width))]
    for top, bottom in zip(borders, borders[1:]):
        if bottom - top < 2:
            continue
        inner_h, inner_w = bottom-top-1, width-2
        holes = {(r-top-1, c-1) for r in range(top+1,bottom) for c in range(1,width-1) if grid[r][c] == 0}
        for color, shape in normalized.items():
            if shape == holes and max((r for r,c in shape), default=-1) < inner_h and max((c for r,c in shape), default=-1) < inner_w:
                for rr, cc in holes:
                    out[top+1+rr][1+cc] = color
                break
    return out
